/*
 * Modified by Actuna Sp. z o.o.:
 *   new module (#40): drains the HTTP requests to the routes of the nodes (httpNode,
 *   in the core: `http in`) before the flows are stopped by a deployment, a reload
 *   from storage or a stop of the flows, and answers the requests that are still open
 *   afterwards (503), so that no accepted request is left without an answer
 *   #76: the code of a failure is read inside a try - a failure whose code cannot be read logs
 *   the code "unknown" and the drain goes on (the other requests are answered, the wait ends)
 *   #63: comment of the set of the entries of the window
 *   #82: the debug record of a 503 names the node of the route (S-1); the guard plans one timeout at the
 *   nearest deadline after the window, skips the entries with a deadline and retries a failed answer in the
 *   window (S-2); isWaitedFor (S-P); waitForShutdown - the wait of a planned shutdown (S-3); the condition
 *   httpDrain of the instance state and the editor notification while a stop waits (S-4); a warning for a
 *   timeout above 300000 ms (S-6)
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * Drain of the HTTP requests before the flows are stopped (#40).
 *
 * A request that `http in` accepted travels through the flow as a message that
 * holds the response (`msg.res`). When the nodes stop - a deployment of any type, a
 * reload from storage (Z-09), `POST /flows/state` stop, a project switch - the
 * message is lost with the node that held it and the client waits for an answer
 * that never comes. With `deploy.drainHttpNodeRequests.enabled: true`:
 *
 *  1. `beforeStop()` waits until the requests that were accepted by an `http in`
 *     node (the snapshot S0) are answered, at most `timeout` ms. Only accepted
 *     requests are waited for, so a client that is slow to send its body or to
 *     authenticate cannot extend the wait.
 *  2. The flows are stopped (flows/index.js `stop`).
 *  3. `afterStop(scope)` answers 503 to the requests that are still open and whose
 *     route was matched: all of them after a full stop, only the ones past their
 *     deadline after a partial stop (`nodes`/`flows`). `finalize()` does the same
 *     when the runtime stops (`RED.stop`).
 *
 * The 503 has the code `http_drain_not_accepted` (the request did not reach a
 * flow: it is safe to repeat) or `http_drain_outcome_unknown` (it did: the flow may
 * have acted). `Retry-After` is sent only for the first code and for the safe methods
 * GET, HEAD and OPTIONS. A response that already started is destroyed instead.
 *
 * Marks (one symbol, two meanings, the runtime owns it):
 * `S = Symbol.for("node-red.httpNode.drain")`.
 *  - On `req` and `res` of every request that enters the httpNode app (only with
 *    the setting enabled): the entry of this module. A node sets `entry.accepted = true`
 *    when it passes the request into a flow, and does nothing when `entry.drained`
 *    is true (the request was already answered with the 503). A node does not
 *    create the entry.
 *  - On a handler of a route (`handler[S] = true`): the route belongs to a node that
 *    follows this contract. Only the requests of such routes are drained: a route
 *    without the mark (for example of a node that does not know the contract) is
 *    left alone.
 * The nodes use `Symbol.for` with the same text, without a `require` of the runtime.
 * A node that leaves its route without the mark (`http in` in the mode "long": SSE,
 * long-poll, #82) is never waited for nor answered here; it closes its own responses.
 *
 * The window. While the flows are stopped and started again the nodes are replaced,
 * and a request that is routed in that time may be orphaned. The window is open from
 * `beforeStop()` to the end of the operation: in a deployment or a reload as long
 * as the instance state is the `deploying` / `reloading` that `beforeStop()` found
 * (compared by `since`, so a later operation does not inherit it - except one that takes
 * the operation over under the same state: a deployment superseded after
 * `deploy.startTimeoutReleasesLock`, which keeps the window until the last start ends), otherwise until
 * `afterStop()`. A request that is routed in the window (it was open when the window
 * opened, or arrived in it) gets the deadline `max(t0, moment of the match) + timeout`;
 * after it the guard answers 503 (also once the window has closed). A request that arrives
 * outside the window has no deadline.
 *
 * Nothing is read from the request stream here, so nothing is read before the
 * authentication (SEC-001 of #16): the middleware runs on the httpNode app after
 * the hold of the requests (#8) and before `rawBodyCapture`.
 *
 * Settings (`deploy.drainHttpNodeRequests`, default off):
 *  - `enabled` (boolean): only `true` enables the drain
 *  - `timeout` (ms, default 30000, at most 2147483647): the longest wait for the
 *    accepted requests, and the distance of the deadline of a routed request; above 300000 a
 *    warning at start (#82)
 *  - `retryAfter` (seconds, integer, default 1): the `Retry-After` header of the 503
 * @module
 */

const { log } = require("@node-red/util");
const instanceState = require("./state");
const httpNodeResponse = require("./httpNodeResponse");
const httpRoutes = require("./nodes/httpRoutes");

const S = Symbol.for("node-red.httpNode.drain");

const DEFAULTS = { timeout: 30000, retryAfter: 1 };
// The largest delay of setTimeout: a larger one fires after 1 ms
const MAX_TIMEOUT = 2147483647;
// A timeout above this is accepted with a warning at start (#82): the drain holds the deploy lock up to it
const LONG_TIMEOUT = 300000;
// The period of the guard: the delay of a deadline that is not set at the moment of the match
const WATCHDOG_PERIOD = 250;
const SAFE_METHODS = new Set(["GET", "HEAD", "OPTIONS"]);
const CODE_NOT_ACCEPTED = "http_drain_not_accepted";
const CODE_OUTCOME_UNKNOWN = "http_drain_outcome_unknown";
const MESSAGE_NOT_ACCEPTED = "The flows are being stopped and the request was not processed, it can be repeated";
const MESSAGE_OUTCOME_UNKNOWN = "The flows were stopped while the request was being processed, its outcome is unknown";

// The code of a failure for the log, "unknown" without one. What fails can be anything (a getter
// that throws, a Proxy), so it is read inside a try and the result is always a string (#76)
function codeText(err) {
    try {
        const code = (err && err.code) || "unknown";
        return typeof code === "string" ? code : "" + code;
    } catch (e) {
        return "unknown";
    }
}

// Runs `fn` for each entry of `list`. A failure of one entry (a request or a response that cannot be
// read) does not stop the others: it is logged once per call with its code (#82: the other requests are
// still answered, the waits still served)
function eachEntry(list, fn) {
    let failed = false;
    let failure;
    list.forEach(function(entry) {
        try {
            fn(entry);
        } catch (err) {
            if (!failed) {
                failed = true;
                failure = err;
            }
        }
    });
    if (failed) {
        log.warn(log._("httpDrain.drain-failed", { code: codeText(failure) }));
    }
}

let config = { enabled: false };
// Every request that entered the httpNode app and is not finished: Set<Entry>
const entries = new Set();
// The entries of the window that have no deadline yet and are not finished. The guard looks at these
// to give them their deadline when their route is matched (#82: an entry leaves the set when it gets
// its deadline); it answers only from `deadlined` (below)
const tracked = new Set();
// The entries that have a deadline and are not finished: the guard answers them when the deadline
// passes, also after the window has closed (a hard limit). Every deadline is finite, so the guard ends
const deadlined = new Set();
// The window: {t0, mode: "state", state, since} or {t0, mode: "operation"}; null outside a stop
let op = null;
// The running waits (#82): the wait of beforeStop() and the waits of the shutdown (waitForShutdown),
// each {pending: Set<Entry>, resolve, timer}. They are independent: each ends on its own requests
const waits = new Set();
// The wait of beforeStop() (also in `waits`), or null
let stopWait = null;
// The one timer of the guard: an interval of WATCHDOG_PERIOD while a window is open or a wait of the
// shutdown runs, otherwise one timeout at the nearest deadline (#82)
let timer = null;
// "period" or "timeout" while `timer` is set
let timerMode = null;
// The moment the timeout is planned for
let timerAt = null;

function isPositiveNumber(value) {
    return typeof value === "number" && isFinite(value) && value > 0;
}

function isPositiveInteger(value) {
    return Number.isInteger(value) && value > 0;
}

function readConfig(settings) {
    const deploy = (settings && settings.deploy) || {};
    const raw = deploy.drainHttpNodeRequests;
    if (raw === undefined || raw === null) {
        return { enabled: false };
    }
    if (typeof raw !== "object" || Array.isArray(raw)) {
        log.warn(log._("httpDrain.invalid-setting", { value: String(raw) }));
        return { enabled: false };
    }
    const result = Object.assign({ enabled: raw.enabled === true }, DEFAULTS);
    [["timeout", value => isPositiveNumber(value) && value <= MAX_TIMEOUT], ["retryAfter", isPositiveInteger]].forEach(function(entry) {
        const key = entry[0];
        if (raw[key] !== undefined) {
            if (entry[1](raw[key])) {
                result[key] = raw[key];
            } else {
                log.warn(log._("httpDrain.invalid-option", { key: key, value: String(raw[key]) }));
            }
        }
    });
    return result;
}

/**
 * Reads the settings. Calling it again (tests, an embedding application) first
 * disposes the state of the earlier call. A drain enabled with a `timeout` above
 * 300000 ms is accepted with one warning (#82).
 * @param {Object} userSettings - the runtime settings (`deploy.drainHttpNodeRequests`)
 */
function init(userSettings) {
    dispose();
    config = readConfig(userSettings);
    if (config.enabled && config.timeout > LONG_TIMEOUT) {
        log.warn(log._("httpDrain.long-timeout", { timeout: config.timeout, limit: LONG_TIMEOUT }));
    }
}

/**
 * Forgets the requests, ends the running waits and stops the guard.
 */
function dispose() {
    config = { enabled: false };
    op = null;
    entries.clear();
    tracked.clear();
    deadlined.clear();
    endAllWaits();
    disarm();
}

/**
 * @return {boolean} whether the drain is enabled (the middleware is to be mounted)
 */
function isEnabled() {
    return config.enabled === true;
}

/**
 * @return {number} the number of the requests that are tracked now (not finished)
 */
function size() {
    return entries.size;
}

// A request that the flows can still answer. A response that has ended (`writableEnded`) is finished,
// also before its 'finish' event (a slow client)
function isOpen(entry) {
    return entries.has(entry) && !entry.res.writableEnded && !entry.res.destroyed && !entry.drained;
}

// isOpen() for the count of a log: a response that cannot be read is counted as closed (#82)
function isOpenForCount(entry) {
    try {
        return isOpen(entry);
    } catch (err) {
        return false;
    }
}

/**
 * The window now, or null. In the mode "state" the window follows the instance
 * state, not an event: it is open while the state is the one `beforeStop()` found
 * and has not been left and entered again (`since`), whatever the order of the
 * listeners of the state is.
 */
function currentOp() {
    if (!op) {
        return null;
    }
    if (op.mode === "state") {
        const current = instanceState.get();
        return (current.state === op.state && current.since === op.since) ? op : null;
    }
    return op;
}

/**
 * Whether the route that the request matched has a handler with the mark of the
 * contract. Express sets `req.route` before the handlers of the route run, so the
 * route is known during the body parsers of the route too. It is read each time: a request
 * that a handler passes on with `next("route")` to a route without the mark is no longer ours.
 * A route that cannot be read (a getter that throws) is not a route of the contract (#82): the
 * request is left alone and the drain goes on with the others.
 */
function isRouted(entry) {
    try {
        const route = entry.req.route;
        return !!route && Array.isArray(route.stack) && route.stack.some(function(layer) { return layer.handle && layer.handle[S] === true });
    } catch (err) {
        return false;
    }
}

/**
 * The one definition of "waited for" (#82, S-P): open, accepted by its node and on a route with the
 * mark. Used by the wait of beforeStop(), the snapshot of waitForShutdown() and the count of the
 * condition of the instance state. The mark of the route is the only carrier of the policy: a node
 * that does not mark its route (`http in` in the mode "long") is never waited for.
 */
function isWaitedFor(entry) {
    return isOpen(entry) && entry.accepted === true && isRouted(entry);
}

function track(entry) {
    tracked.add(entry);
    plan();
}

function setDeadline(entry, from) {
    entry.deadline = Math.max(entry.op.t0, from) + config.timeout;
    deadlined.add(entry);
    // an entry with a deadline is not observed any more (#82)
    tracked.delete(entry);
    plan();
}

/**
 * A request of the httpNode app. `accepted` is the contract with the nodes: the
 * setter notes the moment and, in the window, gives the deadline (the accessor
 * is the exact moment, the guard only observes the route).
 */
class Entry {
    constructor(req, res) {
        this.req = req;
        this.res = res;
        this.op = null;
        this.deadline = null;
        this.acceptedAt = null;
        this.drained = false;
        // a failed answer was logged (the guard retries it in the window without a new warning, #82)
        this.answerFailed = false;
    }

    get accepted() {
        return this.acceptedAt !== null;
    }

    set accepted(value) {
        if (value !== true || this.acceptedAt !== null) {
            return;
        }
        this.acceptedAt = Date.now();
        // A window that has closed in the meantime still gives the deadline: on the safe side
        if (!this.op) {
            this.op = currentOp();
            if (this.op) {
                track(this);
            }
        }
        if (this.op && this.deadline === null) {
            setDeadline(this, this.acceptedAt);
        }
    }
}

// The entry no longer counts for the waits: a wait whose requests have all finished ends
function leaveWaits(entry) {
    Array.from(waits).forEach(function(wait) {
        if (wait.pending.delete(entry) && wait.pending.size === 0) {
            endWait(wait);
        }
    });
}

function onEntryDone(entry) {
    entries.delete(entry);
    tracked.delete(entry);
    deadlined.delete(entry);
    leaveWaits(entry);
    if (timer && !needsGuard()) {
        disarm();
    }
}

/**
 * The Express middleware to be mounted on the httpNode app after the hold of the
 * requests and before any route of a node. It creates the entry and does nothing
 * to the request stream.
 */
function middleware(req, res, next) {
    if (!config.enabled) {
        return next();
    }
    const entry = new Entry(req, res);
    req[S] = entry;
    res[S] = entry;
    entries.add(entry);
    const done = function() { onEntryDone(entry) };
    res.once("finish", done);
    res.once("close", done);
    entry.op = currentOp();
    if (entry.op) {
        track(entry);
    }
    next();
}

function waitedFor() {
    return Array.from(entries).filter(isWaitedFor);
}

// Ends a wait (once): its timer is cleared, its promise resolved
function endWait(wait) {
    if (!waits.has(wait)) {
        return;
    }
    waits.delete(wait);
    clearTimeout(wait.timer);
    wait.resolve();
    if (wait === stopWait) {
        stopWait = null;
    }
    if (timer && !needsGuard()) {
        disarm();
    }
}

function endAllWaits() {
    Array.from(waits).forEach(endWait);
}

function finishWait() {
    if (stopWait) {
        endWait(stopWait);
    }
}

// The guard looks for the requests of the waits whose response has ended without an event yet
function checkWaits() {
    Array.from(waits).forEach(function(wait) {
        eachEntry(Array.from(wait.pending), function(entry) {
            if (!isOpen(entry)) {
                wait.pending.delete(entry);
            }
        });
        if (wait.pending.size === 0) {
            endWait(wait);
        }
    });
}

/**
 * Ends the running wait of `beforeStop()` at once (the runtime stops: `RED.stop`).
 * A wait of the shutdown (`waitForShutdown`) is not ended (#82).
 */
function abortWait() {
    finishWait();
}

/**
 * Opens the window and waits until the accepted requests are answered, at most
 * `timeout` ms. Never rejects. No wait in the state `stopping` (the runtime
 * stops itself, R-37): `finalize()` answers what is left.
 * @return {Promise<void>}
 */
function beforeStop() {
    try {
        if (!config.enabled) {
            return Promise.resolve();
        }
        // The stops are serialised by the caller; a wait that is still running is not left behind
        finishWait();
        const current = instanceState.get();
        const t0 = Date.now();
        op = (current.state === "deploying" || current.state === "reloading")
            ? { t0: t0, mode: "state", state: current.state, since: current.since }
            : { t0: t0, mode: "operation" };
        entries.forEach(function(entry) {
            if (!isOpen(entry)) {
                return;
            }
            entry.op = op;
            // A deadline that passed before this window belongs to an earlier one
            if (isRouted(entry) && (entry.deadline === null || entry.deadline < t0)) {
                entry.deadline = t0 + config.timeout;
                deadlined.add(entry);
            }
            // only an entry without a deadline is observed (#82)
            if (entry.deadline === null) {
                tracked.add(entry);
            } else {
                tracked.delete(entry);
            }
        });
        const waited = waitedFor();
        if (current.state === "stopping" || waited.length === 0) {
            plan();
            return Promise.resolve();
        }
        log.info(log._("httpDrain.waiting", { count: waited.length, timeout: config.timeout }));
        return new Promise(function(resolve) {
            const wait = { pending: new Set(waited), resolve: resolve };
            wait.timer = setTimeout(function() {
                if (waits.has(wait)) {
                    log.warn(log._("httpDrain.timeout", { count: Array.from(wait.pending).filter(isOpenForCount).length }));
                    endWait(wait);
                }
            }, config.timeout);
            waits.add(wait);
            stopWait = wait;
            // after the timer of the wait: at the deadline the wait ends first
            plan();
        });
    } catch (err) {
        log.warn(log._("httpDrain.drain-failed", { code: codeText(err) }));
        return Promise.resolve();
    }
}

/**
 * The wait of a planned shutdown (#82, S-3: `health.shutdown`, the path of a stop signal, before
 * `RED.stop`): waits until the requests that are waited for now (the snapshot) have finished, at most
 * `min(timeout, budgetMs)` ms. Independent of the wait of `beforeStop()`: `abortWait()` does not end
 * it; `cancel()`, `finalize()` and `dispose()` do.
 * @param {number} budgetMs - the time left of `shutdownTimeout`
 * @return {{promise: Promise<void>, cancel: function()}} the promise never rejects; it resolves at
 *     once (without a log) with the drain off, a budget that is not a number greater than 0, or when
 *     no request is waited for
 */
function waitForShutdown(budgetMs) {
    let wait = null;
    const cancel = function() {
        if (wait) {
            endWait(wait);
        }
    };
    try {
        if (!config.enabled || !isPositiveNumber(budgetMs)) {
            return { promise: Promise.resolve(), cancel: cancel };
        }
        const limit = Math.min(config.timeout, budgetMs);
        const waited = waitedFor();
        if (waited.length === 0) {
            return { promise: Promise.resolve(), cancel: cancel };
        }
        log.info(log._("httpDrain.shutdown-waiting", { count: waited.length, timeout: limit }));
        let resolve;
        const promise = new Promise(function(done) { resolve = done });
        wait = { pending: new Set(waited), resolve: resolve };
        wait.timer = setTimeout(function() {
            if (waits.has(wait)) {
                log.warn(log._("httpDrain.shutdown-timeout", { count: Array.from(wait.pending).filter(isOpenForCount).length }));
                endWait(wait);
            }
        }, limit);
        waits.add(wait);
        // the guard sees a response that has ended without an event (no window needed)
        plan();
        return { promise: promise, cancel: cancel };
    } catch (err) {
        log.warn(log._("httpDrain.drain-failed", { code: codeText(err) }));
        cancel();
        return { promise: Promise.resolve(), cancel: cancel };
    }
}

/**
 * Gives the deadline to the requests of the window whose route was matched after
 * the window opened (the guard and `afterStop()` observe the route). The entries
 * that already have a deadline are not in `tracked` (#82).
 */
function observe() {
    const now = Date.now();
    eachEntry(Array.from(tracked), function(entry) {
        if (entry.deadline !== null) {
            tracked.delete(entry);
        } else if (!isOpen(entry)) {
            tracked.delete(entry);
        } else if (entry.op && isRouted(entry)) {
            setDeadline(entry, now);
        }
    });
}

function newCounts() {
    return { notAccepted: 0, outcomeUnknown: 0, destroyed: 0, failed: 0 };
}

function hasCounts(counts) {
    return counts.notAccepted + counts.outcomeUnknown + counts.destroyed + counts.failed > 0;
}

function logCounts(counts, cause) {
    if (hasCounts(counts)) {
        log.warn(log._("httpDrain.answered", Object.assign({ cause: cause }, counts)));
    }
}

// The node of the route of the request (#82, S-1), or null: a route that was not registered by
// `node.registerHttpRoute`, a node without a usable id, or a `req.route` that cannot be read
function ownerOfRequest(req) {
    try {
        return httpRoutes.ownerOf(req.route);
    } catch (err) {
        return null;
    }
}

// An answered request leaves the guard and the waits at once (#82)
function drained(entry) {
    entry.drained = true;
    tracked.delete(entry);
    deadlined.delete(entry);
    leaveWaits(entry);
}

/**
 * Answers a request that the flows can no longer answer. Never throws: an error is
 * logged with its code only (no URL, no text of the error) and `drained` stays
 * unset, so a response that a flow still sends is not lost. The debug record of a
 * 503 names the node of the route when it is known (`id`, `type`, `z`, #82).
 * @param {Entry} entry
 * @param {Object} counts
 * @param {boolean} [retry] - the guard: a failure of an entry whose failure was
 *     already logged is not logged or counted again (#82)
 */
function answer(entry, counts, retry) {
    const req = entry.req;
    const res = entry.res;
    try {
        if (res.writableEnded) {
            return;
        }
        if (res.headersSent) {
            // A response that has started (a stream) cannot be replaced
            res.destroy();
            drained(entry);
            counts.destroyed++;
            return;
        }
        const accepted = entry.accepted;
        const code = accepted ? CODE_OUTCOME_UNKNOWN : CODE_NOT_ACCEPTED;
        httpNodeResponse.sendUnavailable(req, res, {
            code: code,
            message: accepted ? MESSAGE_OUTCOME_UNKNOWN : MESSAGE_NOT_ACCEPTED,
            retryAfter: (!accepted || SAFE_METHODS.has(req.method)) ? config.retryAfter : null,
            close: !req.complete,
            clearHeaders: true
        });
        drained(entry);
        if (accepted) {
            counts.outcomeUnknown++;
        } else {
            counts.notAccepted++;
        }
        const msg = log._("httpDrain.answered-request", { method: String(req.method), code: code });
        const owner = ownerOfRequest(req);
        if (owner) {
            log.log(Object.assign({ level: log.DEBUG }, owner, { msg: msg }));
        } else {
            log.debug(msg);
        }
    } catch (err) {
        if (retry && entry.answerFailed) {
            return;
        }
        entry.answerFailed = true;
        counts.failed++;
        log.warn(log._("httpDrain.answer-failed", { code: codeText(err) }));
    }
}

/**
 * Answers the open requests of a routed route after the flows were stopped. Never throws.
 * @param {"full"|"partial"} scope - `full`: all of them; `partial` (`nodes`/`flows` deployment,
 *     the other flows keep running): the ones past their deadline
 */
function afterStop(scope) {
    try {
        observe();
        const now = Date.now();
        const counts = newCounts();
        eachEntry(Array.from(entries), function(entry) {
            if (isOpen(entry) && isRouted(entry) && (scope === "full" || (entry.deadline !== null && entry.deadline <= now))) {
                answer(entry, counts);
            }
        });
        logCounts(counts, scope === "full" ? "stop" : "timeout");
    } catch (err) {
        log.warn(log._("httpDrain.drain-failed", { code: codeText(err) }));
    } finally {
        // In the mode "state" the window stays open until the operation ends (the start of the new nodes)
        if (op && op.mode === "operation") {
            op = null;
            tracked.clear();
        }
        // after an operation window: one timeout at the nearest deadline (#82)
        plan();
    }
}

/**
 * The runtime stopped the flows (`RED.stop`): answers the requests that are still
 * open and routed, whether or not the flows were running, and ends every wait
 * (also the wait of the shutdown, #82). Never throws.
 */
function finalize() {
    if (!config.enabled) {
        return;
    }
    try {
        const counts = newCounts();
        eachEntry(Array.from(entries), function(entry) {
            if (isOpen(entry) && isRouted(entry)) {
                answer(entry, counts);
            }
        });
        logCounts(counts, "shutdown");
    } catch (err) {
        log.warn(log._("httpDrain.drain-failed", { code: codeText(err) }));
    } finally {
        op = null;
        tracked.clear();
        deadlined.clear();
        endAllWaits();
        disarm();
    }
}

// Whether a wait of the shutdown runs (the guard checks its requests at every period)
function shutdownWaiting() {
    for (const wait of waits) {
        if (wait !== stopWait) {
            return true;
        }
    }
    return false;
}

// Whether the guard runs at every period: a window that has something to look at, or a wait of the shutdown
function needsPeriod(current) {
    return shutdownWaiting() || (current !== null && (stopWait !== null || tracked.size > 0 || deadlined.size > 0));
}

function needsGuard() {
    return deadlined.size > 0 || needsPeriod(currentOp());
}

/**
 * Plans the one timer of the guard (#82): an interval while a window is open with something to look
 * at, or while a wait of the shutdown runs; otherwise, while a request has a deadline, one timeout at
 * the nearest deadline (a timeout that is planned for a later moment is planned again); otherwise none.
 * The timer is unref'ed.
 */
function plan() {
    if (needsPeriod(currentOp())) {
        if (timer && timerMode === "period") {
            return;
        }
        disarm();
        timer = setInterval(tick, WATCHDOG_PERIOD);
        timerMode = "period";
    } else if (deadlined.size > 0) {
        let nearest = Infinity;
        deadlined.forEach(function(entry) {
            if (entry.deadline < nearest) {
                nearest = entry.deadline;
            }
        });
        if (timer && timerMode === "timeout" && timerAt <= nearest) {
            return;
        }
        disarm();
        timer = setTimeout(tick, Math.max(0, nearest - Date.now()));
        timerMode = "timeout";
        timerAt = nearest;
    } else {
        disarm();
        return;
    }
    if (typeof timer.unref === "function") {
        timer.unref();
    }
}

function disarm() {
    if (timer) {
        if (timerMode === "period") {
            clearInterval(timer);
        } else {
            clearTimeout(timer);
        }
        timer = null;
        timerMode = null;
        timerAt = null;
    }
}

/**
 * The guard: while a window is open it gives the deadlines of the requests whose route was
 * matched meanwhile; it ends a wait whose requests have finished (also one whose response has
 * ended without an event); always it answers the routed requests that are past their deadline,
 * also after the window has closed (the limit is hard: a message lost with a stopped node must
 * not leave its request without an answer). In the window an answer that failed is tried again at
 * the next period (logged once); after the window the request leaves the guard (`afterStop("full")`
 * and `finalize()` try again).
 */
function tick() {
    if (timerMode === "timeout") {
        // the timeout has fired: it is planned again below when needed
        timer = null;
        timerMode = null;
        timerAt = null;
    }
    try {
        checkWaits();
        const current = currentOp();
        if (current) {
            observe();
        } else {
            tracked.clear();
        }
        const now = Date.now();
        const counts = newCounts();
        eachEntry(Array.from(deadlined), function(entry) {
            if (!isOpen(entry)) {
                deadlined.delete(entry);
            } else if (entry.deadline <= now) {
                // a request that left the routes of the contract (`next("route")`) is not ours
                const routed = isRouted(entry);
                if (!current || !routed) {
                    // after the window the request leaves the guard before the answer (as before #82)
                    deadlined.delete(entry);
                }
                if (routed) {
                    // an answer that succeeds removes the entry; in the window a failed one stays for a retry
                    answer(entry, counts, true);
                }
            }
        });
        logCounts(counts, "timeout");
        if (current && !current.longWarned && now - current.t0 > 2 * config.timeout) {
            // A start that does not end keeps the window open (the start has its own limits)
            current.longWarned = true;
            log.warn(log._("httpDrain.window-long", { timeout: config.timeout }));
        }
    } catch (err) {
        log.warn(log._("httpDrain.drain-failed", { code: codeText(err) }));
    } finally {
        plan();
    }
}

module.exports = {
    S,
    readConfig,
    init,
    dispose,
    isEnabled,
    size,
    middleware,
    beforeStop,
    abortWait,
    waitForShutdown,
    afterStop,
    finalize
};
